                    'unit_price': '100.50',
                    'total_price': '1005.00'
                },
                {
                    'sku': 'DEF456',
                    'name': 'Test Product 2',
                    'qty': 20,
                    'unit_price': '50.25',
                    'total_price': '1005.00'
                },
            ],
            'metadata': {
                'project_name': 'Test Project',
                'client': 'Test Client'
